mapper.select:
SELECT id, household_id, lot_id, item_id, type, quantity, from_location_id, to_location_id,
       reason, memo, operator_account_id, business_time, created_at, idempotency_key, reversal_of
FROM inventory_movement

    household_id = #{householdId}
    AND type = #{type}
    AND item_id = #{itemId}
    AND (from_location_id = #{locationId} OR to_location_id = #{locationId})
    AND operator_account_id = #{operatorAccountId}
    AND business_time >= #{from}
    AND business_time < #{to}

ORDER BY ${orderBy}

SELECT id, lot_id, item_id, type, quantity, from_location_id, to_location_id,
       reason, operator_account_id, reversal_of, business_time, created_at
FROM inventory_movement
WHERE household_id = #{householdId}
  AND created_at > #{cursor}
ORDER BY created_at ASC
LIMIT #{limit}
